local A=HeroFreePick
local function add(e)
 HeroFreePickCatalog[#HeroFreePickCatalog+1]=e;A.byID[e.id]=e
 HeroRarityCosts[e.id]=e.rarityCost or 0
 HeroBrowseAssignment[e.id]={categories={6},order=0,direct=false}
 HeroFreePickLayout[e.id]={icon=e.icon}
end
for _,e in ipairs(HeroMasteries)do add(e)end
for _,e in ipairs(HeroMasteryExtraAbilities)do add(e)end
for _,m in ipairs(HeroMasteries)do
 local spells={};for _,s in ipairs(m.members)do spells[s]=true end
 for _,e in ipairs(HeroFreePickCatalog)do
  if not A.IsTalent(e)and not e.isMastery then
   for _,s in ipairs(e.spells)do if spells[s]then
    e.requiredMastery=m.id;e.ae=0;e.rarityCost=0;e.displayOnly=nil;HeroRarityCosts[e.id]=0;break
   end end
  end
 end
end
function A.MasteryAllowed(e,rank,key)
 local selected=HeroFreePickPlans[key]or {}
 if rank>0 and e.requiredMastery and (selected[e.requiredMastery]or 0)<1 then
  if A.ShowPointWarning then A.ShowPointWarning('Requires '..A.byID[e.requiredMastery].name..'.')end
  return false
 end
 if rank<=0 and e.isMastery then
  for id,count in pairs(selected)do local member=A.byID[id]
   if count>0 and member and member.requiredMastery==e.id then
    if A.ShowPointWarning then A.ShowPointWarning('Remove mastery abilities first.')end
    return false
   end
  end
 end
 return true
end
-- Preserve prior selections in a backup, then remove members missing their prerequisite.
function A.ValidateMasterySelections()
 local backup
 for _,key in ipairs({'entries','previewLearned'})do
  for id,count in pairs(HeroFreePickPlans[key]or {})do
   local e=A.byID[id]
   if e and e.requiredMastery and count>0 and ((HeroFreePickPlans[key]or {})[e.requiredMastery]or 0)<1 then
    backup=backup or {};backup[key]=backup[key]or {};backup[key][id]=count
    HeroFreePickPlans[key][id]=nil
   end
  end
 end
 if backup then HeroFreePickPlans.masteryMigrationBackup=backup end
end
